function calculate(firstNumber, secondNumber, operator) {
  switch (operator) {
    case 'add':
      return firstNumber + secondNumber;
    case 'subtract':
      return firstNumber - secondNumber;
    case 'multiply':
      return firstNumber * secondNumber;
    case 'divide':
      if (secondNumber === 0) {
        throw new Error('Cannot divide by zero');
      }
      return firstNumber / secondNumber;
    default:
      throw new Error('Unsupported operator');
  }
}

function readNumber(inputId) {
  const value = document.getElementById(inputId).value;

  if (value === '') {
    throw new Error('Please enter both numbers');
  }

  const number = Number(value);

  if (Number.isNaN(number)) {
    throw new Error('Please enter valid numbers');
  }

  return number;
}

function showResult(result) {
  document.getElementById('result').textContent = 'Result: ' + result;
  document.getElementById('error').textContent = '';
}

function showError(message) {
  document.getElementById('result').textContent = 'Result: --';
  document.getElementById('error').textContent = message;
}

function handleCalculate() {
  try {
    const firstNumber = readNumber('firstNumber');
    const secondNumber = readNumber('secondNumber');
    const operator = document.getElementById('operator').value;
    const result = calculate(firstNumber, secondNumber, operator);

    showResult(result);
  } catch (error) {
    showError(error.message);
  }
}

function handleClear() {
  document.getElementById('firstNumber').value = '';
  document.getElementById('secondNumber').value = '';
  document.getElementById('operator').value = 'add';
  document.getElementById('result').textContent = 'Result: --';
  document.getElementById('error').textContent = '';
}

if (typeof document !== 'undefined') {
  document.getElementById('calculateBtn').addEventListener('click', handleCalculate);
  document.getElementById('clearBtn').addEventListener('click', handleClear);
}

if (typeof module !== 'undefined') {
  module.exports = {
    calculate
  };
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  font-family: Arial, sans-serif;
  background: #f5f5f5;
  display: flex;
  align-items: center;
  justify-content: center;
}

.calculator {
  width: 360px;
  padding: 24px;
  background: #ffffff;
  border-radius: 12px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.12);
}

h1 {
  margin-top: 0;
  text-align: center;
}

label {
  display: block;
  margin-top: 12px;
  font-weight: 600;
}

input,
select,
button {
  width: 100%;
  margin-top: 6px;
  padding: 10px;
  font-size: 16px;
}

.actions {
  display: flex;
  gap: 10px;
  margin-top: 16px;
}

.actions button {
  width: 50%;
  cursor: pointer;
}

.result-panel {
  margin-top: 16px;
  padding: 12px;
  background: #f0f0f0;
  border-radius: 8px;
}

.error {
  color: #c00000;
  min-height: 20px;
}

const { calculate } = require('../src/calculator');

function assertEqual(actual, expected, message) {
  if (actual !== expected) {
    throw new Error(message + '. Expected ' + expected + ', got ' + actual);
  }
}

function assertThrows(fn, expectedMessage, message) {
  try {
    fn();
  } catch (error) {
    if (error.message !== expectedMessage) {
      throw new Error(message + '. Expected error message "' + expectedMessage + '", got "' + error.message + '"');
    }
    return;
  }

  throw new Error(message + '. Expected function to throw');
}

assertEqual(calculate(1, 2, 'add'), 3, 'addition should work');
assertEqual(calculate(5, 3, 'subtract'), 2, 'subtraction should work');
assertEqual(calculate(4, 3, 'multiply'), 12, 'multiplication should work');
assertEqual(calculate(8, 2, 'divide'), 4, 'division should work');

assertThrows(
  function () {
    calculate(8, 0, 'divide');
  },
  'Cannot divide by zero',
  'divide by zero should throw'
);

console.log('calculator tests passed');
